mapper.update:
update stall_safety_mark
set score=score + #{mark}
where id = #{id}

update stall_safety_mark
set score     = score - #{mark},
    insp_total=insp_total + #{size}
where id = #{id}

mapper.select:
SELECT DISTINCT s.id, s.project_id, s.`code`, s.area_id1, s.area_id2, s.area_id3, s.company_id, s.`name`, c.`name` AS company_name, c.introduction, c.`owner`, c.mobile, m.`year`, m.score, m.insp_total, e.total, e.z_score_avg, e.s_score_avg, e.t_score_avg, e.w_score_avg, e.honesty_score FROM space s LEFT JOIN company c ON s.company_id = c.id LEFT JOIN (SELECT * FROM stall_safety_mark
WHERE `year` = #{queryDTO.year}
) m ON s.id = m.stall_id LEFT JOIN stall_evaluation e ON s.id = e.stall_id WHERE s.company_id IS NOT NULL AND s.company_id <> '' AND s.deleted = 0
AND s.bim_id =#{queryDTO.bimId}
AND s.id = #{queryDTO.stallId}
AND s.project_id = #{queryDTO.projectId}
AND ( s.`name` LIKE concat('%',#{queryDTO.search},'%') OR c.`name` LIKE concat('%',#{queryDTO.search},'%') OR c.`owner` LIKE concat('%',#{queryDTO.search},'%') OR c.`mobile` = #{queryDTO.search} )
AND IF(m.score IS NULL, 100, m.score) BETWEEN #{queryDTO.minScore} AND #{queryDTO.maxScore}
ORDER BY m.insp_total DESC, e.total DESC
